<script setup lang="ts">
import {onMounted,ref} from 'vue';const token=new URLSearchParams(location.search).get('service-feedback')??'';const safe=new URL(location.href);safe.searchParams.delete('service-feedback');history.replaceState({},'',safe.pathname+safe.search);const ready=ref(false),submitted=ref(false),ticket=ref(''),error=ref(''),busy=ref(false),score=ref(5),comment=ref('');
async function request(method='GET',body?:unknown){const r=await fetch('/api/v1/service-feedback/'+encodeURIComponent(token),{method,credentials:'omit',headers:{'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});const data=await r.json();if(!r.ok)throw new Error(data.message||'评价链接无效或已过期');return data;}
onMounted(async()=>{try{const r=await request();ticket.value=r.ticketNumber;submitted.value=r.submitted;ready.value=true;}catch(e){error.value=(e as Error).message;}});async function submit(){busy.value=true;error.value='';try{await request('POST',{score:Number(score.value),comment:comment.value});submitted.value=true;}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
</script><template><main class="p6" style="max-width:640px;margin:10vh auto;padding:20px"><section class="p6-card"><span class="eyebrow">SERVICE FEEDBACK</span><h1>服务评价</h1><p v-if="ticket" class="p6-muted">工单 {{ticket}}</p><div v-if="error" class="p6-error" role="alert">{{error}}</div><p v-if="submitted" role="status">评价已提交，感谢你的反馈。</p><form v-else-if="ready" @submit.prevent="submit"><label>本次服务满意度<select v-model="score"><option value="5">5分 · 非常满意</option><option value="4">4分 · 满意</option><option value="3">3分 · 一般</option><option value="2">2分 · 不满意</option><option value="1">1分 · 很不满意</option></select></label><label>建议（选填）<textarea v-model="comment" rows="5" maxlength="2000"/></label><button class="btn primary" :disabled="busy">{{busy?'正在提交…':'提交评价'}}</button></form></section></main></template>
